/* Bit-exact C model for dd13_ax2_ssss_midori_513 (generated by mk_c_impl.py, mixed layers).
 * Construction: 4r mixed NL (SSSS), rk_r = rotl64(k, 13u * (unsigned)(r + 1)) ^ RC[r] */
#include <stdint.h>

static const uint8_t SBOX_R0[16] = {12, 10, 13, 3, 14, 11, 15, 7, 8, 9, 1, 5, 0, 2, 4, 6};
static const uint8_t SBOX_R1[16] = {12, 10, 13, 3, 14, 11, 15, 7, 8, 9, 1, 5, 0, 2, 4, 6};
static const uint8_t SBOX_R2[16] = {12, 10, 13, 3, 14, 11, 15, 7, 8, 9, 1, 5, 0, 2, 4, 6};
static const uint8_t SBOX_R3[16] = {12, 10, 13, 3, 14, 11, 15, 7, 8, 9, 1, 5, 0, 2, 4, 6};

static const uint8_t PBOX[64] = {1, 20, 39, 58, 13, 32, 51, 6, 25, 44, 63, 18, 37, 56, 11, 30, 49, 4, 23, 42, 61, 16, 35, 54, 9, 28, 47, 2, 21, 40, 59, 14, 33, 52, 7, 26, 45, 0, 19, 38, 57, 12, 31, 50, 5, 24, 43, 62, 17, 36, 55, 10, 29, 48, 3, 22, 41, 60, 15, 34, 53, 8, 27, 46};

static const uint64_t RC[4] = {0x9E3779B97F4A7C15ULL, 0x3C6EF372FE94F82AULL, 0xDAA66D2C7DDF743FULL, 0x78DDE6E5FD29F054ULL};

static uint64_t rotl64(uint64_t x, unsigned r) {
    r &= 63;
    return r ? (x << r) | (x >> (64 - r)) : x;
}

uint64_t mix_hash(uint64_t v, uint64_t k) {
    uint64_t x = v;
    for (int r = 0; r < 4; r++) {
        uint64_t rk = (rotl64(k, 13u * (unsigned)(r + 1))) ^ RC[r];
        uint64_t t = x ^ rk;
        uint64_t y;
        switch (r) {
            case 0: { /* S-box round */
                y = 0;
                for (int n = 0; n < 16; n++)
                    y |= (uint64_t)SBOX_R0[(t >> (4*n)) & 0xF] << (4*n);
                break;
            }
            case 1: { /* S-box round */
                y = 0;
                for (int n = 0; n < 16; n++)
                    y |= (uint64_t)SBOX_R1[(t >> (4*n)) & 0xF] << (4*n);
                break;
            }
            case 2: { /* S-box round */
                y = 0;
                for (int n = 0; n < 16; n++)
                    y |= (uint64_t)SBOX_R2[(t >> (4*n)) & 0xF] << (4*n);
                break;
            }
            case 3: { /* S-box round */
                y = 0;
                for (int n = 0; n < 16; n++)
                    y |= (uint64_t)SBOX_R3[(t >> (4*n)) & 0xF] << (4*n);
                break;
            }
            default: y = t; break;
        }
        /* P-box */
        uint64_t z = 0;
        for (int i = 0; i < 64; i++)
            z |= ((y >> i) & 1ULL) << PBOX[i];
        if (r == 0) z = z ^ rotl64(z, 5) ^ rotl64(z, 13);
        if (r == 1) z = z ^ rotl64(z, 5) ^ rotl64(z, 13);
        if (r == 2) z = z ^ rotl64(z, 5) ^ rotl64(z, 13);
        if (r == 3) z = z ^ rotl64(z, 5) ^ rotl64(z, 13);
        x = z;
    }
    return x;
}
